package local.beatsync;
import android.app.*;import android.os.*;import android.content.*;import android.media.*;import android.media.projection.*;import android.util.Base64;import org.json.*;import java.net.*;import java.io.*;
public class CastService extends Service {
 volatile boolean active;MediaProjection projection;AudioRecord record;String base,code,token;HttpURLConnection presence,upload;Thread worker;
 public IBinder onBind(Intent i){return null;}
 void notice(String text){Notification n=new Notification.Builder(this,"cast").setContentTitle("BeatSync Wi-Fi audio").setContentText(text).setSmallIcon(android.R.drawable.ic_media_play).setOngoing(active).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(1,n);}
 public int onStartCommand(Intent i,int f,int id){if(i==null)return START_NOT_STICKY;if(active)return START_NOT_STICKY;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("cast","Audio casting",NotificationManager.IMPORTANCE_LOW));active=true;startForeground(1,new Notification.Builder(this,"cast").setContentTitle("BeatSync").setContentText("Connecting to your Wi-Fi room…").setSmallIcon(android.R.drawable.ic_media_play).build());base=i.getStringExtra("url").replaceAll("/+$","");code=i.getStringExtra("room");Intent permission=i.getParcelableExtra("projection");projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(Activity.RESULT_OK,permission);projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},new Handler(getMainLooper()));worker=new Thread(()->cast());worker.start();return START_NOT_STICKY;}
 JSONObject post(String path,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();upload=c;try{c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);byte[] data=body.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(data.length);try(OutputStream out=c.getOutputStream()){out.write(data);}int status=c.getResponseCode();InputStream in=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null)try(InputStream input=in){byte[] b=new byte[4096];int n;while((n=input.read(b))>0)out.write(b,0,n);}JSONObject result=new JSONObject(out.toString("UTF-8"));if(status>=400)throw new IOException(result.optString("error","HTTP "+status));return result;}finally{c.disconnect();upload=null;}}
 void cast(){String error=null;try{JSONObject joined=post("/api/rooms/"+code+"/join",new JSONObject().put("name",Build.MODEL+" · Android app audio"));token=joined.getString("token");presence=(HttpURLConnection)new URL(base+"/api/rooms/"+code+"/events?token="+token).openConnection();presence.setConnectTimeout(5000);presence.setReadTimeout(30000);presence.getInputStream();new Thread(()->{try{byte[] b=new byte[4096];while(active&&presence.getInputStream().read(b)>=0){}}catch(Exception e){if(active){notice("Room disconnected. Reconnect from BeatSync.");stopSelf();}}}).start();post("/api/rooms/"+code+"/action",new JSONObject().put("type","phone-start"));AudioPlaybackCaptureConfiguration cfg=new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).addMatchingUsage(AudioAttributes.USAGE_UNKNOWN).build();AudioFormat fmt=new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_IN_STEREO).build();int size=Math.max(38400,AudioRecord.getMinBufferSize(48000,AudioFormat.CHANNEL_IN_STEREO,AudioFormat.ENCODING_PCM_16BIT)*2);record=new AudioRecord.Builder().setAudioFormat(fmt).setBufferSizeInBytes(size).setAudioPlaybackCaptureConfig(cfg).build();record.startRecording();notice("Sharing app audio over Wi-Fi. Open your music app.");byte[] chunk=new byte[19200];long seq=0;while(active){int used=0;while(active&&used<chunk.length){int n=record.read(chunk,used,chunk.length-used);if(n<=0)throw new IOException("Audio capture stopped: "+n);used+=n;}if(active)post("/api/rooms/"+code+"/action",new JSONObject().put("type","phone-audio").put("seq",seq++).put("pcm",Base64.encodeToString(chunk,Base64.NO_WRAP)));}}catch(Exception e){error=e.getMessage();}finally{if(token!=null)try{post("/api/rooms/"+code+"/action",new JSONObject().put("type","leave"));}catch(Exception e){}if(error!=null){active=false;notice("Could not cast: "+error);stopForeground(false);}stopSelf();}}
 public void onDestroy(){active=false;if(upload!=null)upload.disconnect();if(presence!=null)presence.disconnect();if(record!=null){try{record.stop();}catch(Exception e){}record.release();}if(projection!=null)projection.stop();super.onDestroy();}
}
